  require.Error(t, err)
  require.Contains(t, err.Error(), tc.key)
  if tc.name == \"invalid protocol\" { require.Contains(t, err.Error(), \"oracle\"); require.True(t, strings.Contains(err.Error(), \"postgres\") && strings.Contains(err.Error(), \"mysql\") && strings.Contains(err.Error(), \"sqlite\")) }
 }) }
}
EOF
